using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
public static class SetupMinimap {
 static RectTransform Rect(GameObject go,Transform parent,Vector2 anchor,Vector2 position,Vector2 size){var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=anchor;r.pivot=anchor;r.anchoredPosition=position;r.sizeDelta=size;return r;}
 static void Label(string name,Transform parent,string text,Vector2 anchor,Vector2 position,Vector2 size,Color color,TextAlignmentOptions alignment){var go=new GameObject(name,typeof(RectTransform),typeof(TextMeshProUGUI));Rect(go,parent,anchor,position,size);var label=go.GetComponent<TextMeshProUGUI>();label.font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/Nunito/Nunito-Bold SDF.asset");label.text=text;label.fontSize=17;label.alignment=alignment;label.color=color;label.raycastTarget=false;}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!="Assets/Scenes/TestTrackScene.unity")throw new System.Exception("Expected test track in Edit mode.");var hud=GameObject.Find("TestDriveHUD");if(!hud)throw new System.Exception("HUD missing.");if(GameObject.Find("MinimapPanel"))throw new System.Exception("Minimap already exists.");var panel=new GameObject("MinimapPanel",typeof(RectTransform),typeof(UnityEngine.UI.Image));Undo.RegisterCreatedObjectUndo(panel,"Add circuit minimap");Rect(panel,hud.transform,new Vector2(1,1),new Vector2(-40,-40),new Vector2(360,230));panel.GetComponent<UnityEngine.UI.Image>().color=new Color(.035f,.045f,.06f,.92f);panel.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;
 var gold=new Color(.98f,.77f,.25f);var accent=new GameObject("MinimapAccent",typeof(RectTransform),typeof(UnityEngine.UI.Image));Rect(accent,panel.transform,new Vector2(0,1),Vector2.zero,new Vector2(360,4));accent.GetComponent<UnityEngine.UI.Image>().color=gold;accent.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;Label("MinimapHeading",panel.transform,"CIRCUIT",new Vector2(0,1),new Vector2(20,-16),new Vector2(120,25),new Color(.75f,.79f,.83f),TextAlignmentOptions.Left);Label("MinimapLegend",panel.transform,"YOU",new Vector2(1,1),new Vector2(-20,-16),new Vector2(80,25),gold,TextAlignmentOptions.Right);
 var go=new GameObject("CircuitMap",typeof(RectTransform),typeof(CanvasRenderer),typeof(TestDriveMinimap));Rect(go,panel.transform,Vector2.zero,new Vector2(16,14),new Vector2(328,172));var map=go.GetComponent<TestDriveMinimap>();map.color=new Color(.72f,.77f,.82f);map.raycastTarget=false;var road=GameObject.Find("Asphalt — 12m wide").GetComponent<MeshFilter>();var so=new SerializedObject(map);so.FindProperty("roadMesh").objectReferenceValue=road.sharedMesh;so.FindProperty("roadTransform").objectReferenceValue=road.transform;so.FindProperty("vehicle").objectReferenceValue=Object.FindAnyObjectByType<TestDriveMovement>().transform;
 var bounds=new Bounds(new Vector3(-17.65f,0,-25),Vector3.zero);foreach(var t in GameObject.Find("Start finish markings").GetComponentsInChildren<Transform>()){if(t.name!="Checker")continue;bounds.Encapsulate(t.GetComponent<Renderer>().bounds);}so.FindProperty("startLineA").vector3Value=new Vector3(bounds.center.x,0,bounds.min.z);so.FindProperty("startLineB").vector3Value=new Vector3(bounds.center.x,0,bounds.max.z);so.ApplyModifiedProperties();map.SetAllDirty();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=panel;return "Saved whole-circuit minimap, start/finish line, and live position/heading arrow in top-right HUD.";}
}
